HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>RateCommons Explorer</title>\n<style>\n:root{--bg:#f7f6f2;--panel:#fff;--ink:#1d2024;--muted:#6b7078;--line:#e3e1da;--accent:#1f6f5c;--accent-ink:#fff;--warn:#9a3b1b;--chip:#eef3f1}\n@media (prefers-color-scheme:dark){:root{--bg:#141618;--panel:#1c1f22;--ink:#e8e6e1;--muted:#9aa0a6;--line:#2c3034;--accent:#5bbf9f;--accent-ink:#0d1210;--warn:#f08b65;--chip:#20302b}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}\nheader{padding:20px 24px 8px;max-width:1280px;margin:0 auto}\nh1{font-size:22px;margin:0 0 4px;letter-spacing:-.01em}\nheader p{margin:0;color:var(--muted);max-width:860px}\nmain{max-width:1280px;margin:0 auto;padding:12px 24px 40px;display:grid;grid-template-columns:230px 1fr;gap:20px}\nnav{display:flex;flex-direction:column;gap:4px;position:sticky;top:12px;align-self:start}\nnav button{all:unset;cursor:pointer;padding:9px 12px;border-radius:8px;color:var(--ink)}\nnav button:hover{background:var(--chip)}\nnav button.on{background:var(--accent);color:var(--accent-ink);font-weight:600}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px}\n.card h2{margin:0 0 4px;font-size:18px}\n.card .desc{color:var(--muted);margin:0 0 14px;font-size:14px;white-space:pre-line}\nform{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px 14px;align-items:end}\nlabel{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}\ntextarea{font:13px/1.45 ui-monospace,Menlo,Consolas,monospace;width:100%;box-sizing:border-box;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:8px 10px;resize:vertical}\nlabel.wide{grid-column:1/-1;flex-basis:100%;width:100%}\n.hint{display:block;font-size:12px;color:var(--muted,#777);margin-top:4px;text-transform:none;letter-spacing:0}\ninput,select{font:inherit;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:8px;padding:8px 10px;text-transform:none;letter-spacing:0}\ninput:focus,select:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.go{grid-column:1/-1;display:flex;gap:10px;align-items:center}\n.go button{font:inherit;font-weight:600;background:var(--accent);color:var(--accent-ink);border:0;border-radius:8px;padding:9px 18px;cursor:pointer}\n.go button.sec{background:transparent;color:var(--accent);border:1px solid var(--line)}\n.status{color:var(--muted);font-size:13px}\n.err{color:var(--warn)}\n.tablewrap{margin-top:16px;overflow:auto;max-height:68vh;border:1px solid var(--line);border-radius:10px}\ntable{border-collapse:collapse;width:100%;font-size:13px}\nth,td{padding:7px 10px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap;vertical-align:top}\nth{position:sticky;top:0;background:var(--panel);cursor:pointer;font-weight:600;z-index:1}\ntd.num{text-align:right;font-variant-numeric:tabular-nums}\ntr:hover td{background:var(--chip)}\n.ai{margin-top:20px;font-size:14px}\n.ai code{background:var(--chip);padding:2px 6px;border-radius:6px;word-break:break-all}\n.note{font-size:13px;color:var(--muted);margin-top:14px}\n@media (max-width:820px){main{grid-template-columns:1fr;padding:12px 16px}nav{flex-direction:row;flex-wrap:wrap;position:static}header{padding:16px 16px 4px}}\n</style>\n</head>\n<body>\n<header>\n<h1>RateCommons Explorer</h1>\n<p>Negotiated prices that Cigna, Aetna and UnitedHealthcare publish under the Transparency in Coverage rule, by code, place and provider.\nA missing rate means <b>no published rate</b>, not out of network. Rates are contract amounts, not a patient\'s cost.</p>\n</header>\n<main>\n<nav id="nav"></nav>\n<section>\n<div class="card" id="panel"></div>\n<div class="card ai">\n<b>Use your AI as the analyst.</b> Add this as a custom connector (MCP) in Claude or ChatGPT:\n<code id="mcpurl"></code><br><span class="note">No login or key. Then ask in plain English, e.g. "What do Cigna, Aetna and UHC pay for a 99214 in Houston, and how does that compare with Medicare?"</span>\n<div class="note" id="status"></div>\n</div>\n</section>\n</main>\n<script>\nconst VIEWS = [\n  ["lookup_rates", "Rates lookup", {code:"99213", state:"MO", city:"Saint Louis"}],\n  ["market_distribution", "Market spread", {code:"99214", state:"MO", group_by:"product"}],\n  ["provider_rates", "A provider\'s rates", {codes:"99213,99214", state:"MO"}],\n  ["compare_providers", "Compare providers", {codes:"99213,99214", state:"MO"}],\n  ["benchmark_provider", "Benchmark a practice", {codes:"99213,99214,99215", state:"MO"}],\n  ["network_breadth", "Network breadth", {state:"MO", specialty:"Cardiovascular Disease"}],\n  ["find_plans", "Plans & networks", {query:"Choice"}],\n  ["search_providers", "Find providers", {state:"MO", city:"Saint Louis"}],\n  ["rank_providers", "Rank groups (national)", {codes:"70450,71250,74177,72148", state:"US", specialty:"Radiology"}],\n  ["run_sql", "Custom SQL", {sql:"SELECT payer, count(DISTINCT tin) AS groups, median(rate) AS median_rate\\nFROM rc_rates(\'all\', \'MO\', \'99213\', \'\', \'office\')\\nWHERE negotiated_type = \'negotiated\' AND rate > 0.01 AND rate < 99999\\nGROUP BY payer ORDER BY payer"}],\n  ["code_info", "Code info", {code:"70553"}],\n  ["medicare_rate", "Medicare fee schedule", {codes:"99213,99214", state:"MO"}],\n  ["data_status", "Data status", {}],\n];\nconst CHOICES = {payer:["all","cigna","aetna","uhc"], billing_class:["","professional","institutional"],\n  group_by:["payer","product","setting","none"], place:["office","facility","any"], modifier:["","26","TC"]};\nlet TOOLS = {}, current = null, lastRows = [];\nconst $ = s => document.querySelector(s);\nconst esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;"}[c]));\nconst nice = k => k.replace(/_/g," ");\n\nasync function init(){\n  $("#mcpurl").textContent = location.origin + "/mcp";\n  try { const t = await (await fetch("/api/tools")).json(); t.forEach(x => TOOLS[x.name] = x); }\n  catch(e){ $("#panel").innerHTML = \'<p class="err">Could not reach the API.</p>\'; return; }\n  const nav = $("#nav");\n  VIEWS.forEach(([name,title]) => { const b = document.createElement("button"); b.textContent = title; b.onclick = () => show(name); b.dataset.n = name; nav.appendChild(b); });\n  show(location.hash.slice(1) || "lookup_rates");\n  fetch("/api/tool/data_status",{method:"POST",headers:{"content-type":"application/json"},body:"{}"}).then(r=>r.json()).then(d=>{\n    if(d.payers) $("#status").textContent = "Loaded: " + Object.entries(d.payers).map(([p,v])=>`${p} (${v.networks} networks, ${(v.codes||0).toLocaleString()} codes)`).join(" · ");\n  }).catch(()=>{});\n}\n\nfunction show(name){\n  const v = VIEWS.find(x => x[0] === name) || VIEWS[0]; current = v[0]; location.hash = current;\n  document.querySelectorAll("nav button").forEach(b => b.classList.toggle("on", b.dataset.n === current));\n  const t = TOOLS[current]; if(!t) return;\n  const props = t.inputSchema.properties, req = t.inputSchema.required || [];\n  let html = `<h2>${esc(v[1])}</h2><p class="desc">${esc(t.description.split("\\n\\n")[0])}</p><form id="f">`;\n  for (const [k,p] of Object.entries(props)){\n    const val = v[2][k] ?? p.default ?? "";\n    const tip = esc(p.description || "");\n    if (CHOICES[k]) html += `<label title="${tip}">${nice(k)}<select name="${k}">${CHOICES[k].map(o=>`<option ${o==val?"selected":""}>${o}</option>`).join("")}</select></label>`;\n    else if (k === "sql") html += `<label class="wide">${nice(k)} *<textarea name="sql" rows="9" spellcheck="false">${esc(val)}</textarea><span class="hint">Table functions: rc_rates, rc_rates_by_product, rc_medicare, rc_groups, rc_group_npis, rc_nppes, rc_codes, rc_products (details in the tool description)</span></label>`;\n    else html += `<label title="${tip}">${nice(k)}${req.includes(k)?" *":""}<input name="${k}" value="${esc(val)}" placeholder="${tip.slice(0,60)}"></label>`;\n  }\n  html += `<div class="go"><button>Run</button><button type="button" class="sec" id="csv" disabled>Download CSV</button><span class="status" id="st"></span></div></form><div id="out"></div>`;\n  $("#panel").innerHTML = html;\n  $("#f").onsubmit = e => { e.preventDefault(); run(); };\n  $("#csv").onclick = csv;\n}\n\nasync function run(){\n  const fd = new FormData($("#f")), body = {};\n  for (const [k,v] of fd.entries()) if (v !== "") body[k] = v;\n  $("#st").className = "status"; $("#st").textContent = "Running…"; $("#out").innerHTML = ""; $("#csv").disabled = true;\n  const t0 = performance.now();\n  try {\n    const d = await (await fetch("/api/tool/" + current, {method:"POST", headers:{"content-type":"application/json"}, body: JSON.stringify(body)})).json();\n    const secs = ((performance.now()-t0)/1000).toFixed(1);\n    if (!d.ok){ $("#st").className = "status err"; $("#st").textContent = d.error; return; }\n    let rows = d.rows; if (!rows){ const {ok, seconds, ...rest} = d; rows = [rest]; }\n    lastRows = rows; $("#st").textContent = `${rows.length.toLocaleString()} rows · ${secs}s` + (d.notes && d.notes.length ? ` · ${d.notes.length} note(s): ${d.notes.slice(0,3).join("; ")}` : "") + (d.truncated ? " · truncated" : ""); $("#csv").disabled = !rows.length;\n    $("#out").innerHTML = rows.length ? table(rows) : \'<p class="note">No published rates match. (No published rate is not the same as out of network.)</p>\';\n    document.querySelectorAll("#out th").forEach((th,i) => th.onclick = () => sortBy(i));\n  } catch(e){ $("#st").className = "status err"; $("#st").textContent = "Request failed: " + e; }\n}\n\nfunction fmt(v){\n  if (v === null || v === undefined) return "";\n  if (Array.isArray(v)) return esc(v.join(", "));\n  if (typeof v === "object") return esc(JSON.stringify(v));\n  if (typeof v === "number") return Number.isInteger(v) ? v.toLocaleString() : v.toLocaleString(undefined,{maximumFractionDigits:2});\n  return esc(v);\n}\nfunction table(rows){\n  const cols = [...new Set(rows.flatMap(r => Object.keys(r)))];\n  return `<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${esc(nice(c))}</th>`).join("")}</tr></thead><tbody>` +\n    rows.slice(0,2000).map(r => `<tr>${cols.map(c => `<td class="${typeof r[c]==="number"?"num":""}">${fmt(r[c])}</td>`).join("")}</tr>`).join("") + "</tbody></table></div>";\n}\nlet sortState = {i:-1, dir:1};\nfunction sortBy(i){\n  const cols = [...new Set(lastRows.flatMap(r => Object.keys(r)))], k = cols[i];\n  sortState = {i, dir: sortState.i === i ? -sortState.dir : 1};\n  lastRows.sort((a,b) => { const x=a[k], y=b[k]; return (x===y?0:(x===null||x===undefined)?1:(y===null||y===undefined)?-1:(x<y?-1:1))*sortState.dir; });\n  $("#out").innerHTML = table(lastRows); document.querySelectorAll("#out th").forEach((th,j) => th.onclick = () => sortBy(j));\n}\nfunction csv(){\n  const cols = [...new Set(lastRows.flatMap(r => Object.keys(r)))];\n  const q = v => { v = v===null||v===undefined ? "" : Array.isArray(v) ? v.join("; ") : String(v); return /[",\\n]/.test(v) ? \'"\' + v.replace(/"/g,\'""\') + \'"\' : v; };\n  const text = [cols.join(","), ...lastRows.map(r => cols.map(c => q(r[c])).join(","))].join("\\n");\n  const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([text],{type:"text/csv"})); a.download = current + ".csv"; a.click();\n}\ninit();\n</script>\n</body>\n</html>\n'
